    def __init__(self, date, time, location, sport_type):
        self.date = date
        self.time = time
        self.location = location
        self.sport_type = sport_type
        self.schedule = {}
        self.teams = {}
        self.referees = {}
        self.participants = {}

    def add_team(self, team_name, team_members):
        self.teams[team_name] = team_members

